CREATE FUNCTION guard_agent_sandbox() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF ROW(NEW.id, NEW.workspace_id, NEW.subject_key, NEW.kind, NEW.claim_name, NEW.created_at, NEW.shutdown_at)
    IS DISTINCT FROM ROW(OLD.id, OLD.workspace_id, OLD.subject_key, OLD.kind, OLD.claim_name, OLD.created_at, OLD.shutdown_at) THEN
  RAISE EXCEPTION 'a sandbox''s identity is immutable' USING ERRCODE = '55000';
 END IF;
 IF OLD.state = 'DELETING' AND NEW.state <> 'DELETING' THEN
  RAISE EXCEPTION 'a sandbox that is being deleted is never live again' USING ERRCODE = '55000';
 END IF;
 IF OLD.state = 'READY' AND NEW.state = 'REQUESTED' THEN
  RAISE EXCEPTION 'a ready sandbox is never requested again' USING ERRCODE = '23514';
 END IF;
 IF NEW.last_used_at < OLD.last_used_at THEN
  RAISE EXCEPTION 'a sandbox''s last use never goes back' USING ERRCODE = '23514';
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER agent_sandbox_transition BEFORE UPDATE ON agent_sandbox FOR EACH ROW EXECUTE FUNCTION guard_agent_sandbox();
